#!/usr/bin/env node
/**
 * bake-car-sprites.js
 *
 * Bakes the four drivers' car sprites from the SAME formula car the 3D mode
 * drives, so the two views of the game finally agree about what the cars are.
 *
 *   in  : madring-3d/public/models/f1car-2026.glb — project-authored model
 *         from APEX FORMULA 2026 (Apache-2.0; see NOTICE section 2. Its
 *         ASSET_PROVENANCE.md declares it generated by tools/blender/
 *         build_car.py with no third-party logos or likenesses).
 *   out : images/car-oso.png, car-gata.png, car-cibeles.png, car-madrono.png
 *         — 104×152 px, i.e. 4× the 26×38 the game displays, nose up,
 *         transparent background, contact shadow and outline baked in.
 *
 *     node scripts/bake-car-sprites.js
 *     DEBUG=1 node scripts/bake-car-sprites.js   # also dumps the raw render
 *
 * How the sprite is built
 * ───────────────────────
 * An orthographic camera looks straight down (+Z of the model — its nose —
 * pointing screen-up) and renders the car once per driver, with the body
 * paint replaced by the exact clearcoat recipe madring-3d's Chassis.tsx uses
 * (MeshPhysicalMaterial, metalness 0.9, roughness 0.4, clearcoat 1.0,
 * clearcoatRoughness 0.03) tinted with that driver's CHAR_COLORS entry, under
 * the same sort of sky environment the overhead bake uses — clearcoat paint
 * is nothing but what it reflects.
 *
 * A real F1 car is ~2.7× longer than wide; drawn honestly at a 38 px length
 * it would be 14 px wide and vanish on the aerial. The camera therefore
 * widens the car by WIDEN (1.30) — the same cheat every top-down racer makes
 * — and the wheels/body still read.
 *
 * Compositing, all sized to survive the 4× downscale to 26×38:
 *   · a soft black halo (two blurred passes), radially symmetric on purpose:
 *     the sprite rotates with the car, so a directional shadow would swing
 *     around as you steer;
 *   · a hard dark outline (8-direction stamp of the silhouette), because on
 *     the baked aerial the asphalt can be the same value as the paint;
 *   · the car itself.
 *
 * BootScene loads these files and falls back to the procedural genDrivers()
 * cars if they are missing, so a failed bake costs art, not a playable game.
 */
'use strict';

const fs = require('fs');
const http = require('http');
const path = require('path');
const { chromium } = require('playwright');

const ROOT = path.join(__dirname, '..');
const OUT_DIR = path.join(ROOT, 'images');
const DEBUG = !!process.env.DEBUG;

// Keep in step with game.js: NAMES / CHAR_COLORS order.
const DRIVERS = [
    { file: 'car-oso.png',     color: 0xd8892c },   // OSO
    { file: 'car-gata.png',    color: 0x4f8fe0 },   // GATA
    { file: 'car-cibeles.png', color: 0x46c2a8 },   // CIBELES
    { file: 'car-madrono.png', color: 0xd8452f },   // MADROÑO
];

const SPRITE_W = 104, SPRITE_H = 152;   // 4× the 26×38 display size
const SS = 4;                            // supersample factor for the bake
const WIDEN = 1.30;                      // lateral exaggeration (see header)

const MIME = { '.js': 'text/javascript', '.mjs': 'text/javascript', '.glb': 'model/gltf-binary',
               '.gltf': 'model/gltf+json', '.bin': 'application/octet-stream',
               '.png': 'image/png', '.jpg': 'image/jpeg', '.html': 'text/html' };

function serve(pageHtml) {
    return new Promise(resolve => {
        const srv = http.createServer((req, res) => {
            const rel = decodeURIComponent(req.url.split('?')[0]);
            if (rel === '/') { res.writeHead(200, { 'Content-Type': 'text/html' }).end(pageHtml); return; }
            if (rel === '/favicon.ico') { res.writeHead(204).end(); return; }
            const file = path.join(ROOT, rel);
            if (!file.startsWith(ROOT) || !fs.existsSync(file) || fs.statSync(file).isDirectory()) {
                res.writeHead(404).end('no'); return;
            }
            res.writeHead(200, { 'Content-Type': MIME[path.extname(file)] || 'application/octet-stream' });
            fs.createReadStream(file).pipe(res);
        });
        srv.listen(0, '127.0.0.1', () => resolve(srv));
    });
}

const PAGE = `<!doctype html><meta charset=utf8><style>html,body{margin:0;background:#222}</style>
<script type="importmap">{"imports":{"three":"/madring-3d/node_modules/three/build/three.module.js"}}</script>
<script type="module">
import * as THREE from 'three';
import { GLTFLoader } from '/madring-3d/node_modules/three/examples/jsm/loaders/GLTFLoader.js';
window.THREE = THREE;
window.__ready = new Promise((resolve, reject) => {
    new GLTFLoader().load('/madring-3d/public/models/f1car-2026.glb',
        g => { window.__gltf = g; resolve(true); },
        undefined,
        e => reject(String(e)));
});
</script>`;

(async () => {
    const srv = await serve(PAGE);
    const port = srv.address().port;

    const browser = await chromium.launch({
        headless: true, executablePath: '/opt/pw-browsers/chromium',
        args: ['--enable-unsafe-swiftshader', '--disable-dev-shm-usage'],
    });
    const page = await browser.newPage({ viewport: { width: 800, height: 600 } });
    page.on('console', m => { if (m.type() === 'error') console.log('  [page]', m.text()); });
    page.on('pageerror', e => console.log('  [page error]', e.message));

    await page.goto(`http://127.0.0.1:${port}/`);
    process.stdout.write('loading model… ');
    await page.waitForFunction('window.__ready !== undefined', null, { timeout: 60000 });
    await page.evaluate('window.__ready');
    console.log('ok');

    const results = await page.evaluate(async ({ DRIVERS, SPRITE_W, SPRITE_H, SS, WIDEN, DEBUG }) => {
        const THREE = window.THREE;
        const scene = new THREE.Scene();
        const car = window.__gltf.scene;
        scene.add(car);

        // ── material finishing, following madring-3d/src/models/vehicle/Chassis.tsx ──
        // The glb ships neutral Blender materials named body / accent / carbon /
        // tyre / glass / glow / rainlight; the finishing is done at load time.
        const paint = new THREE.MeshPhysicalMaterial({
            metalness: 0.9, roughness: 0.4, clearcoat: 1.0, clearcoatRoughness: 0.03,
            envMapIntensity: 1,
        });
        const accentPaint = new THREE.MeshPhysicalMaterial({
            metalness: 0.9, roughness: 0.4, clearcoat: 1.0, clearcoatRoughness: 0.03,
            envMapIntensity: 1,
        });
        car.traverse(o => {
            if (!o.isMesh) return;
            const m = Array.isArray(o.material) ? o.material[0] : o.material;
            if (!m) return;
            switch (m.name) {
                case 'carbon': m.color.setHex(0x343842); m.metalness = 0.12; m.roughness = 0.46; break;
                case 'tyre':   m.color.setHex(0x111114); m.metalness = 0.03; m.roughness = 0.9; break;
                case 'glass':  m.color.setHex(0x10141a); m.metalness = 0.92; m.roughness = 0.08; break;
                case 'body':   o.material = paint; break;
                case 'accent': accentPaint.color.copy(m.color); o.material = accentPaint; break;
                // Rear lights lit red: at 26×38 px a red tail is the fastest
                // "that end is the back" cue after the helmet.
                case 'glow':      m.color.setHex(0x120602); m.emissive.setHex(0xff2618); m.emissiveIntensity = 2.0; m.toneMapped = false; break;
                case 'rainlight': m.color.setHex(0x240303); m.emissive.setHex(0xff2618); m.emissiveIntensity = 3.0; m.toneMapped = false; break;
            }
        });

        // ── lighting: mostly overhead, so the shading stays valid as the sprite rotates ──
        scene.add(new THREE.AmbientLight(0xffffff, 0.65));
        const key = new THREE.DirectionalLight(0xfff4e0, 0.9);
        key.position.set(0.25, 1, 0.15).multiplyScalar(10);
        scene.add(key);
        const fill = new THREE.DirectionalLight(0xdfe8ff, 0.35);
        fill.position.set(-0.3, 1, -0.2).multiplyScalar(10);
        scene.add(fill);

        const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true, preserveDrawingBuffer: true });
        renderer.setPixelRatio(1);
        renderer.setSize(SPRITE_W * SS, SPRITE_H * SS, false);
        renderer.outputEncoding = THREE.sRGBEncoding;
        renderer.toneMapping = THREE.NoToneMapping;
        renderer.setClearColor(0x000000, 0);

        // Sky for the clearcoat and the metals to reflect — bright above,
        // ground tone below, same idea as the overhead bake's environment.
        const skyCv = document.createElement('canvas');
        skyCv.width = 64; skyCv.height = 64;
        const sctx = skyCv.getContext('2d');
        const sg = sctx.createLinearGradient(0, 0, 0, 64);
        sg.addColorStop(0.00, '#cfe2f8'); sg.addColorStop(0.48, '#eef4fb');
        sg.addColorStop(0.52, '#8a8274'); sg.addColorStop(1.00, '#5c554a');
        sctx.fillStyle = sg; sctx.fillRect(0, 0, 64, 64);
        const skyTex = new THREE.CanvasTexture(skyCv);
        skyTex.mapping = THREE.EquirectangularReflectionMapping;
        const pmrem = new THREE.PMREMGenerator(renderer);
        scene.environment = pmrem.fromEquirectangular(skyTex).texture;

        // ── camera: straight down, nose pointing screen-up ──
        // The model's nose is +Z (wheel_fl sits at z=+1.55, wheel_rl at
        // z=-1.6). With the camera looking down -Y and up = world +Z, screen
        // up is +Z, so the nose already points up; verified by measuring the
        // baked tyres (the top pair comes out narrower — fronts).
        const box = new THREE.Box3().setFromObject(car);
        const size = box.getSize(new THREE.Vector3());
        const ctr = box.getCenter(new THREE.Vector3());
        // Content footprint in the sprite: leave room for halo + outline.
        const MARGIN = 10;                              // px at 1× (of 104×152)
        const contentH = SPRITE_H - MARGIN * 2;         // car length in px
        const contentW = contentH * (size.x / size.z) * WIDEN;
        const halfH = (size.z / 2) * (SPRITE_H / contentH);
        const halfW = (size.x / 2) * (SPRITE_W / contentW);
        const cam = new THREE.OrthographicCamera(-halfW, halfW, halfH, -halfH, 0.1, 100);
        cam.position.set(ctr.x, ctr.y + 20, ctr.z);
        cam.up.set(0, 0, 1);                             // screen-up = model +Z = nose
        cam.lookAt(ctr.x, ctr.y, ctr.z);
        cam.updateProjectionMatrix();

        const W = SPRITE_W * SS, H = SPRITE_H * SS;
        const silhouette = (src) => {                    // black copy of the alpha
            const c = document.createElement('canvas');
            c.width = W; c.height = H;
            const x = c.getContext('2d');
            x.drawImage(src, 0, 0);
            x.globalCompositeOperation = 'source-in';
            x.fillStyle = '#000';
            x.fillRect(0, 0, W, H);
            return c;
        };

        const out = [];
        for (const d of DRIVERS) {
            paint.color.setHex(d.color).convertSRGBToLinear();
            renderer.render(scene, cam);

            const render = document.createElement('canvas');
            render.width = W; render.height = H;
            render.getContext('2d').drawImage(renderer.domElement, 0, 0);
            const sil = silhouette(render);

            const cv = document.createElement('canvas');
            cv.width = W; cv.height = H;
            const x = cv.getContext('2d');

            // contact-shadow halo: two blurred passes of the silhouette
            x.save();
            for (const blur of [16 * (SS / 4), 8 * (SS / 4)]) {
                x.filter = `blur(${blur}px)`;
                x.globalAlpha = 0.75;
                x.drawImage(sil, 0, 0);
            }
            x.restore();
            x.filter = 'none'; x.globalAlpha = 1;

            // hard dark outline: stamp the silhouette in 8 directions
            const r = 2.2 * (SS / 4);
            for (let k = 0; k < 8; k++) {
                const a = k * Math.PI / 4;
                x.drawImage(sil, Math.cos(a) * r, Math.sin(a) * r);
            }

            x.drawImage(render, 0, 0);

            // downscale to the shipped 104×152
            const fin = document.createElement('canvas');
            fin.width = SPRITE_W; fin.height = SPRITE_H;
            const fx = fin.getContext('2d');
            fx.imageSmoothingEnabled = true; fx.imageSmoothingQuality = 'high';
            fx.drawImage(cv, 0, 0, SPRITE_W, SPRITE_H);
            out.push({ file: d.file, data: fin.toDataURL('image/png'),
                       raw: DEBUG ? render.toDataURL('image/png') : null });
        }
        return { sprites: out, bbox: { x: size.x, y: size.y, z: size.z } };
    }, { DRIVERS, SPRITE_W, SPRITE_H, SS, WIDEN, DEBUG });

    console.log(`model bbox : ${results.bbox.x.toFixed(2)} wide × ${results.bbox.z.toFixed(2)} long × ${results.bbox.y.toFixed(2)} tall (m)`);
    for (const s of results.sprites) {
        const file = path.join(OUT_DIR, s.file);
        fs.writeFileSync(file, Buffer.from(s.data.split(',')[1], 'base64'));
        console.log(`wrote images/${s.file} (${SPRITE_W}×${SPRITE_H})`);
        if (s.raw) {
            fs.writeFileSync(file.replace('.png', '-raw.png'), Buffer.from(s.raw.split(',')[1], 'base64'));
        }
    }

    await browser.close();
    srv.close();
})().catch(e => { console.error(e); process.exit(1); });
